    function run(uint256 depositAmount, uint256 amount) public payable {
        require(address(this).balance >= depositAmount);
        bool depRevert;
        try c.deposit{value: depositAmount}() { depRevert = false; } catch { depRevert = true; }
        require(!depRevert);

        uint256 beforeBal = address(c).balance;

        bool reverted;
        try c.withdraw(amount) { reverted = false; } catch { reverted = true; }

        uint256 afterBal = address(c).balance;

        if (amount <= depositAmount) {
            assert(!reverted);
            assert(beforeBal - afterBal == amount);
        } else {
            assert(reverted);
            assert(afterBal == beforeBal);
        }
    }

    receive() external payable {}
}

